sys_script_include.script:
var dhInstance = function dhInstance(related_id,entity) {

	if ( entity ) { this.entity = entity; }

	this.related_id    = related_id;

	this.days = [];
};

dhInstance.prototype = {

	type: 'dhInstance'
};

//------------------------------------------------
// Public property methods
//------------------------------------------------

dhInstance.prototype.getRelatedTable = function getRelatedTable() {
	return this.getEntity().getRelatedTable();
};

dhInstance.prototype.getRelatedId = function getRelatedId() {
	return this.related_id;
};

dhInstance.prototype.getRelatedRecord = function getRelatedRecord() {

	if ( this._record ) { return this._record; }

	var rr = new GlideRecord(this.getRelatedTable());
	rr.get(this.getRelatedId());

	if ( !rr.isValidRecord() ) { return null; }

	this._record = rr;

	return this._record;
};

dhInstance.prototype.getEntity = function getEntity() {

	if ( this.entity ) { return this.entity; }

	this.entity = dhEntity.getDeviceEntity();

	return this.entity;
};

dhInstance.prototype.getName = function getName() {
	return this.getCache().name || '';
};

dhInstance.prototype.getDayData = function getDayData() {
	return this.days || [];
};

dhInstance.prototype.getDays = function getDays() {
	return this.getCache().days || [];
};

dhInstance.prototype.toString = function toString() {
	return this.type + ' "' + this.getName() + '" [' + this.getRelatedTable() + ':' + this.getRelatedId() + ']';
};

//------------------------------------------------
// Public access methods
//------------------------------------------------

dhInstance.prototype.getMetricItems = function getMetricItems(category) {

	var resp = {
		name     : this.getName(),
		date     : '',
		metrics  : [],
	};

	// Generate response for the latest day
	var day = this.getDays()[0];

	gs.info(JSON.stringify(this.getDays(), null, 2));

	if ( !day || !day.metrics.length ) {
		resp.error = 'No data collected for this item';
		return resp;
	}

	resp.date = day.date;

	var entity = this.getEntity();

	// Prepare response
	day.metrics.forEach(function(m) {

		var metric = entity.getMetric(m.metric_id);

		// If a category was supplied, filter out non matching metrics
		if ( category && category != metric.getCategory() ) { return; }

		var item = {
			name     : metric.getName(),
			label    : metric.getLabel(),
			category : metric.getCategory(),
			unit     : metric.getUnit(),
			value    : m.value
		};

		resp.metrics.push(item);
	});

	return resp;
};

dhInstance.prototype.getMetricValues = function getMetricValues(category) {

	var resp = {
		values : {}
	};

	// Generate response for the latest day
	var day    = this.getDays()[0];

	if ( !day || !day.metrics.length ) {
		resp.error = 'No data collected for this item';
		return resp;
	}

	resp.date = day.date;

	var entity = this.getEntity();

	// Prepare response
	day.metrics.forEach(function(m) {

		var metric = entity.getMetric(m.metric_id);

		// If a category was supplied, filter out non matching metrics
		if ( category && category != metric.getCategory() ) { return; }

		var name = metric.getName();
		var val  = m.value;

		resp.values[name] = val;
	});

	return resp;
};

//------------------------------------------------
// Internal support methods
//------------------------------------------------

dhInstance.prototype.getCache = function getCache() {

	if ( this.cache ) { return this.cache; }

	this.cache = new dhCache().getInstanceData(this);

	return this.cache;
};
